import{HUB as R}from'./registration.mjs';import{PINS}from'./environment-pins.mjs';import{prepareHubSupport,pinnedBytes}from'./support.mjs';import{compose}from'./compose.mjs';
export async function prepareHubRegion({signal,fetcher=fetch,decode=b=>createImageBitmap(new Blob([b],{type:'image/png'})),canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}={}){let closed=false,support=null,source=null,payload=null,canvas=null;const images=[],signs=[];const check=()=>{if(closed||signal?.aborted)throw Error('HUB_ABORTED')};const dispose=()=>{if(closed)return;closed=true;support?.dispose();for(const im of images.splice(0))im.close?.();signs.length=0;source=payload=null;if(canvas)canvas.width=canvas.height=1;canvas=null;signal?.removeEventListener('abort',dispose)};
 const image=async pin=>{check();const im=await decode(await pinnedBytes(pin,{signal,fetcher}));images.push(im);check();return im};const read=async pin=>(await pinnedBytes(pin,{signal,fetcher})).slice(0);
 try{support=await prepareHubSupport({signal,fetcher});const im=await image(R.image);if(im.width!==3456||im.height!==1728)throw Error('HUB_IMAGE_SIZE');canvas=canvasFactory(3456,1728);const g=canvas.getContext('2d');g.drawImage(im,0,0);source=g.getImageData(0,0,3456,1728).data;im.close?.();images.splice(images.indexOf(im),1);canvas.width=960;canvas.height=540;
 const parse=async name=>JSON.parse(new TextDecoder().decode(await read(PINS[name])));payload={sourceRGBA:source,lightManifest:await parse('LIGHT_MANIFEST.json'),waterManifest:await parse('WATER_MANIFEST.json'),lightIds:new Uint32Array(await read(PINS['light_indices.u32'])),lightTransmission:new Float64Array(await read(PINS['light_transmission.f64'])),waterIds:new Uint32Array(await read(PINS['water_indices.u32'])),waterEdge:new Float64Array(await read(PINS['water_edge.f64']))};for(const s of R.signs){const im=await image(s.pin);if(im.width!==96||im.height!==96)throw Error('HUB_SIGN_SIZE');signs.push({image:im,origin:s.native.worldOrigin})}check();signal?.addEventListener('abort',dispose,{once:true});
 }catch(e){dispose();throw e}
 const render=(camera,elapsedMs=0,{nightMix=0,effects=true}={})=>{check();if(!Array.isArray(camera)||camera.length!==4||!camera.every(Number.isInteger))throw Error('HUB_CAMERA');const[x,y,w,h]=camera;if(x<0||y<0||w<1||h<1||x+w>3456||y+h>1728)throw Error('HUB_CAMERA');canvas.width=w;canvas.height=h;const g=canvas.getContext('2d'),im=g.createImageData(w,h);for(let row=0;row<h;row++)im.data.set(source.subarray(((y+row)*3456+x)*4,((y+row)*3456+x+w)*4),row*w*4);g.putImageData(im,0,0);for(const s of signs)g.drawImage(s.image,s.origin[0]-x,s.origin[1]-y);const out=g.getImageData(0,0,w,h).data;const result=compose(out,payload,{sourceSHA:R.image.sha256,verified:true,alreadyApplied:false,elapsedMs,nightMix,camera,effects});if(!result.available)throw Error('HUB_COMPOSE_'+result.reason);return out};
 return Object.freeze({...support,registration:R,get pinsVerified(){return !closed},render,draw(ctx,{camera=[0,0,960,540],elapsedMs=0,nightMix=0,lights=true}={}){const data=render(camera,elapsedMs,{nightMix,effects:lights});const im=ctx.createImageData(camera[2],camera[3]);im.data.set(data);ctx.putImageData(im,0,0)},dispose});
}
